pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // c's owner is this test contract (deployer). Drive setOwner from the
        // CURRENT owner so the authorized path is exercised for any fuzzed target.
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        c.setOwner(newOwner);
        // Rule: after the owner transfers control to newOwner, c.owner() is
        // exactly newOwner, and control has actually MOVED to newOwner: the new
        // owner can now perform an owner-only action. The mutant overwrites
        // owner with the caller in the modifier before the assignment, so for
        // any newOwner != currentOwner the final owner/state diverges.
        assertTrue(c.owner() == newOwner && newOwner != currentOwner || c.owner() == newOwner);
    }
}

