// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 n) public {
        // Wide domain: any uint256, then derive the candidate address from it.
        // bound to a small range so the zero address is reachable by the fuzzer
        // (n == 0 -> address(0)) while still sampling many distinct addresses.
        n = bound(n, 0, 1023);
        address newOwner = address(uint160(n));
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: the owner may always transfer ownership to any address;
        // the call succeeds and owner becomes the requested address.
        assertTrue(ok && c.owner() == newOwner);
    }
}
